action.mutation:
mutation CreateMaintenanceCompletion($payload: [MaintenanceCompletionCreatePayloadInput!]!) {
  mutation: createMaintenanceCompletion(payload: $payload) { 
    id
    number
  }
}

mutation UpdateMaintenanceCompletion($payload: [MaintenanceCompletionUpdatePayloadInput!]!) {
  mutation: updateMaintenanceCompletion(payload: $payload) { 
    id
    number
  }
}

mutation DeleteMaintenanceCompletion($payload: [MaintenanceCompletionDeletePayloadInput!]!) {
  mutation: deleteMaintenanceCompletion(payload: $payload) { 
    id
    number
  }
}
